{ ${\left(2 x + 2\right) \left(y - 8\right)}$  }
   { ${x + y - 7}$  }
     { \True ${2 x + 2 y - 14}$  }
    {  ${\left(4 x + 4\right) \left(y - 8\right)}$  }
\loigiai{
Tích của hai số/biến được viết bằng phép nhân (hoặc viết liền nhau): đáp án đúng là ${2 x + 2 y - 14}$.
}\end{ex}

\begin{ex}%[7D7H1]
Viết biểu thức đại số biểu thị chu vi của một hình chữ nhật có chiều dài là ${x+5}$ cm và chiều rộng là ${y-2}$.
\choice
{ ${x + y + 3}$  }
   { ${\left(2 x + 10\right) \left(y - 2\right)}$  }
     {  ${\left(4 x + 20\right) \left(y - 2\right)}$  }
    { \True ${2 x + 2 y + 6}$  }
\loigiai{
Tích của hai số/biến được viết bằng phép nhân (hoặc viết liền nhau): đáp án đúng là ${2 x + 2 y + 6}$.
}\end{ex}

\begin{ex}%[7D7H1]
Viết biểu thức đại số biểu thị tổng của ${-4x}$ và ${-3y}$
\choice
{ ${- 4 x - 3 y - 2}$  }
   {  $\dfrac{- 4 x - 3 y}{2}$  }
     { \True ${- 4 x - 3 y}$  }
    { ${12 x y}$  }
\loigiai{
Tích của hai số/biến được viết bằng phép nhân (hoặc viết liền nhau): đáp án đúng là ${- 4 x - 3 y}$.
}\end{ex}

\begin{ex}%[7D7H1]
Viết biểu thức đại số biểu thị $15$ lần tổng của ${a}$ và ${b}$
\choice
{  ${15 a + b}$  }
   { ${\left(a + 15\right) \left(b + 15\right)}$  }
     { ${\dfrac{\left(a + 15\right) \left(b + 15\right)}{4}}$  }
    { \True ${15 a + 15 b}$  }
\loigiai{
Tích của hai số/biến được viết bằng phép nhân (hoặc viết liền nhau): đáp án đúng là ${15 a + 15 b}$.
}\end{ex}

\begin{ex}%[7D7H1]
Viết biểu thức đại số biểu thị diện tích của hình chữ nhật có chiều rộng là ${a}$ cm và chiều dài hơn chiều rộng $8$ cm
\choice
{ ${a \left(a + 10\right)}$  }
   { ${a \left(a + 9\right)}$  }
     { \True ${a \left(a + 8\right)}$  }
    {  ${a \left(a - 8\right)}$  }
\loigiai{
Tích của hai số/biến được viết bằng phép nhân (hoặc viết liền nhau): đáp án đúng là ${a \left(a + 8\right)}$.
}\end{ex}

\begin{ex}%[7D7H1]
Viết biểu thức đại số biểu thị diện tích của một hình vuông có chu vi là ${a+7}$ cm.
\choice
{ ${\dfrac{a}{4} + \dfrac{7}{4}}$  }
   { \True ${\left(\dfrac{a}{4} + \dfrac{7}{4}\right)^{2}}$  }
     {  ${\left(a + 7\right)^{2}}$  }
    { ${\left(\dfrac{a}{2} + \dfrac{7}{2}\right)^{2}}$  }
\loigiai{
Tích của hai số/biến được viết bằng phép nhân (hoặc viết liền nhau): đáp án đúng là ${\left(\dfrac{a}{4} + \dfrac{7}{4}\right)^{2}}$.
}\end{ex}
